import { useEffect, useMemo, useRef, useState } from 'react';
import type { FormEvent, PointerEvent as ReactPointerEvent, WheelEvent } from 'react';
import { Icon } from './icons';
import type { AnalysisProject, CodingUnit, Interview, ParticipantDetails, ProjectRecord, ThemeNode, TranscriptSegment } from './domain';
import { childrenOf, createProject, emptyDetails, isThemeDescendant, removeCodingUnit, saveCodingUnit, selectedText, themePath, themePathName, themeUsage, touch } from './domain';
import { createInterview, downloadJSON, exportQuotesXLSX, exportTranscriptXLSX, parseTranscript, readProjectBackup } from './importExport';
import { importProject, listProjects, saveProject } from './storage';
import { AUDIO_EXTENSIONS, MAX_AUDIO_SIZE, deleteOpenAIKey, detailsWithTranscriptionProvenance, diarizedTranscriptSegments, displayAudioTime, openAIStatus, saveOpenAIKey, speakersOf, suggestedSpeakerNames, transcribeAudio, type OpenAIStatus, type TranscriptionResult } from './transcription';
import { createThemeMapLayout, themeEvidence, type ThemeEvidenceItem } from './themeMap';

type Section = 'add' | 'participants' | 'transcript' | 'coding' | 'coded' | 'overview' | 'map' | 'profile' | 'frequency' | 'miles' | 'prevalence' | 'framework';
type Locale = 'tr' | 'en';

const colors = ['#0a84ff', '#5856d6', '#af52de', '#ff453a', '#ff9f0a', '#30d158', '#64d2ff', '#bf5af2'];
const labels = {
  tr: { projects: 'Projeler', newProject: 'Yeni Proje', participants: 'Katılımcılar', transcript: 'Transkript', coding: 'Kodlama', coded: 'Kodlanmış Alıntılar', overview: 'Tüm Görüşmeler', map: 'Tema Haritası', ready: 'Hazır', settings: 'Ayarlar', backup: 'Yedek', addParticipant: 'Katılımcı Ekle' },
  en: { projects: 'Projects', newProject: 'New Project', participants: 'Participants', transcript: 'Transcript', coding: 'Coding', coded: 'Coded Quotes', overview: 'All Interviews', map: 'Theme Map', ready: 'Ready', settings: 'Settings', backup: 'Backup', addParticipant: 'Add Participant' },
};

const navGroups: Array<[string, Array<[Section, string, string]>]> = [
  ['GÖRÜŞME VE KODLAMA', [['add', 'Katılımcı Ekle', 'personPlus'], ['participants', 'Katılımcılar', 'people'], ['transcript', 'Transkript', 'table'], ['coding', 'Kodlama', 'tag'], ['coded', 'Kodlanmış Alıntılar', 'filter']]],
  ['PROJE ANALİZİ', [['overview', 'Tüm Görüşmeler', 'people'], ['map', 'Tema Haritası', 'map']]],
  ['ANALİTİK GÖRÜNÜMLER', [['profile', 'Baskınlık Profili', 'chart'], ['frequency', 'İçerik Analizi', 'chart'], ['miles', 'Miles–Huberman Matrisi', 'grid'], ['prevalence', 'Katılımcı Yaygınlığı', 'people'], ['framework', 'Framework Matrix', 'table']]],
];

export default function App() {
  const [records, setRecords] = useState<ProjectRecord[]>([]);
  const [activeID, setActiveID] = useState<string | null>(null);
  const [section, setSection] = useState<Section>('participants');
  const [selectedInterviewID, setSelectedInterviewID] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [status, setStatus] = useState('Hazır');
  const [error, setError] = useState<string | null>(null);
  const [showNewProject, setShowNewProject] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [theme, setTheme] = useState(localStorage.getItem('ta-appearance') ?? 'light');
  const [locale, setLocale] = useState<Locale>((localStorage.getItem('ta-locale') as Locale) || 'tr');
  const [mobileMenu, setMobileMenu] = useState(false);

  const activeRecord = records.find((record) => record.id === activeID) ?? null;
  const project = activeRecord?.project ?? null;
  const selectedInterview = project?.interviews.find((interview) => interview.id === selectedInterviewID) ?? project?.interviews[0] ?? null;

  useEffect(() => {
    listProjects().then(setRecords).catch((reason) => setError(`Projeler açılamadı: ${message(reason)}`)).finally(() => setLoading(false));
  }, []);
  useEffect(() => { document.documentElement.dataset.theme = theme; localStorage.setItem('ta-appearance', theme); }, [theme]);
  useEffect(() => { localStorage.setItem('ta-locale', locale); document.documentElement.lang = locale; }, [locale]);
  useEffect(() => {
    if (project && !project.interviews.some((interview) => interview.id === selectedInterviewID)) setSelectedInterviewID(project.interviews[0]?.id ?? null);
  }, [project, selectedInterviewID]);

  async function commit(nextProject: AnalysisProject, nextStatus = 'Değişiklikler kaydedildi') {
    if (!activeRecord) return;
    const next = { id: activeRecord.id, project: touch(nextProject) };
    setRecords((current) => current.map((record) => record.id === next.id ? next : record));
    setStatus('Kaydediliyor…');
    try { await saveProject(next); setStatus(nextStatus); }
    catch (reason) { setError(`Kaydetme hatası: ${message(reason)}`); setStatus('Kaydetme başarısız'); }
  }

  async function createNew(name: string) {
    const trimmed = name.trim(); if (!trimmed) return;
    try {
      const record = await importProject(createProject(trimmed));
      setRecords((current) => [record, ...current]); setActiveID(record.id); setSection('participants'); setShowNewProject(false); setStatus('Proje oluşturuldu');
    } catch (reason) { setError(`Proje oluşturulamadı: ${message(reason)}`); }
  }

  async function restore(file: File) {
    try {
      const result = await readProjectBackup(file);
      const record = await importProject(result.project);
      setRecords((current) => [record, ...current]); setStatus(result.migrated ? 'Eski web yedeği güvenli biçimde dönüştürüldü' : 'Proje yedeği açıldı');
    } catch (reason) { setError(`Yedek açılamadı: ${message(reason)}`); }
  }

  if (loading) return <div className="app-loading"><img src="/brand-mark.png" alt="" /><span>Projeler hazırlanıyor…</span></div>;
  const t = labels[locale];
  if (!project) return <><Library records={records} onOpen={(id) => { setActiveID(id); setSection('participants'); }} onNew={() => setShowNewProject(true)} onRestore={restore} onSettings={() => setShowSettings(true)} t={t} />{showNewProject && <NewProjectModal onClose={() => setShowNewProject(false)} onCreate={createNew} />}{showSettings && <SettingsModal theme={theme} locale={locale} setTheme={setTheme} setLocale={setLocale} onClose={() => setShowSettings(false)} />}{error && <AlertModal message={error} onClose={() => setError(null)} />}</>;

  return <main className="workspace-shell">
    <aside className={`sidebar ${mobileMenu ? 'mobile-open' : ''}`}>
      <div className="sidebar-brand"><img src="/brand-mark.png" alt="" /><div><strong>Tematik Analiz</strong><span>{project.name}</span></div></div>
      <nav>{navGroups.map(([group, items]) => <div className="nav-group" key={group}><label>{group}</label>{items.map(([id, title, icon]) => <button className={`nav-item ${section === id ? 'active' : ''}`} key={id} onClick={() => { setSection(id); setMobileMenu(false); }}><Icon name={icon} size={17} /><span>{translateNav(title, locale)}</span></button>)}</div>)}</nav>
      <div className="sidebar-footer"><button className="button small grow" onClick={() => setActiveID(null)}><Icon name="grid" size={15} /> {t.projects}</button><button className="button small icon-button" aria-label={t.settings} onClick={() => setShowSettings(true)}><Icon name="settings" size={15} /></button></div>
    </aside>
    {mobileMenu && <button className="sidebar-scrim" aria-label="Menüyü kapat" onClick={() => setMobileMenu(false)} />}
    <section className="workspace-main">
      <header className="topbar"><button className="mobile-menu-button" aria-label="Menü" onClick={() => setMobileMenu(true)}><Icon name="menu" /></button><h1>{translateNav(sectionTitle(section), locale)}</h1><div className="top-actions">{project.interviews.length > 0 && <select aria-label="Görüşme" value={selectedInterview?.id ?? ''} onChange={(event) => setSelectedInterviewID(event.target.value)}>{project.interviews.map((interview) => <option key={interview.id} value={interview.id}>{interview.name} · {interview.participant}</option>)}</select>}<button className="button small" onClick={() => downloadJSON(project)}><Icon name="save" size={15} /> {t.backup}</button></div></header>
      <div className="content-area">
        <SectionView section={section} project={project} interview={selectedInterview} commit={commit} selectInterview={setSelectedInterviewID} go={setSection} />
      </div>
      <footer className="statusbar"><span className={`status-dot ${status.includes('başarısız') ? 'error' : ''}`} /><span>{status}</span><span className="status-end">IndexedDB · şema v1</span></footer>
    </section>
    {showNewProject && <NewProjectModal onClose={() => setShowNewProject(false)} onCreate={createNew} />}
    {showSettings && <SettingsModal theme={theme} locale={locale} setTheme={setTheme} setLocale={setLocale} onClose={() => setShowSettings(false)} />}
    {error && <AlertModal message={error} onClose={() => setError(null)} />}
  </main>;
}

function Library({ records, onOpen, onNew, onRestore, onSettings, t }: { records: ProjectRecord[]; onOpen: (id: string) => void; onNew: () => void; onRestore: (file: File) => void; onSettings: () => void; t: typeof labels.tr }) {
  return <main className="welcome-shell"><aside className="welcome-panel"><div className="brand-block"><img src="/brand-mark.png" alt="" /><h1>Tematik Analiz</h1><p>Görüşmeleri düzenleyin, kodlayın ve temalar arasındaki ilişkileri keşfedin.</p></div><div className="welcome-actions"><button className="button primary large" onClick={onNew}><Icon name="plus" /> {t.newProject}</button><label className="button large"><Icon name="folder" /> Proje Yedeği Aç…<input type="file" accept=".json,.zip,application/json,application/zip" hidden onChange={(event) => { const file = event.target.files?.[0]; if (file) onRestore(file); event.target.value = ''; }} /></label></div><div className="welcome-spacer" /><button className="text-button" onClick={onSettings}><Icon name="settings" /> {t.settings}</button></aside><section className="library-panel"><header className="library-header"><div><h2>{t.projects}</h2><p>Son çalışmalarınız</p></div><span>{records.length} proje</span></header><div className="project-list">{records.length ? records.map((record, index) => { const units = record.project.interviews.reduce((sum, interview) => sum + interview.codingUnits.length, 0); return <button className="project-row stagger" style={{ '--i': index } as React.CSSProperties} key={record.id} onClick={() => onOpen(record.id)}><span className="project-icon"><Icon name="table" size={20} /></span><span className="project-info"><strong>{record.project.name}</strong><small>{record.project.interviews.length} katılımcı · {units} kodlama</small></span><span className="project-date"><small>Son düzenleme</small><span>{formatDate(record.project.updatedAt)}</span></span><Icon name="chevron" size={16} /></button>; }) : <Empty icon="grid" title="Henüz proje yok" description="İlk tematik analiz projenizi oluşturun veya macOS yedeğinizi açın." />}</div><footer>Projeler bu tarayıcıda, ayrı ve sürümlü IndexedDB kayıtları olarak saklanır.</footer></section></main>;
}

function SectionView({ section, project, interview, commit, selectInterview, go }: { section: Section; project: AnalysisProject; interview: Interview | null; commit: (project: AnalysisProject, status?: string) => Promise<void>; selectInterview: (id: string) => void; go: (section: Section) => void }) {
  if (section === 'add') return <ParticipantForm project={project} commit={commit} onSaved={(id) => { selectInterview(id); go('coding'); }} onCancel={() => go('participants')} />;
  if (section === 'participants') return <Participants project={project} commit={commit} selectInterview={selectInterview} go={go} />;
  if (section === 'transcript') return <Transcript project={project} interview={interview} commit={commit} />;
  if (section === 'coding') return <Coding project={project} interview={interview} commit={commit} />;
  if (section === 'coded') return <CodedQuotes project={project} commit={commit} />;
  if (section === 'overview') return <Overview project={project} selectInterview={selectInterview} go={go} />;
  if (section === 'map') return <ThemeMap project={project} commit={commit} />;
  return <Analytics project={project} type={section} />;
}

function Participants({ project, commit, selectInterview, go }: { project: AnalysisProject; commit: (p: AnalysisProject, s?: string) => Promise<void>; selectInterview: (id: string) => void; go: (s: Section) => void }) {
  const [editing, setEditing] = useState<Interview | null>(null);
  return <div className="page fade-in"><PageHeader title="Katılımcılar" subtitle="Her katılımcı kendi transkripti ve demografik bilgileriyle saklanır." action={<button className="button primary" onClick={() => go('add')}><Icon name="plus" size={16} /> Katılımcı Ekle</button>} />{project.interviews.length ? <div className="table-wrap"><table><thead><tr><th>Katılımcı</th><th>Cinsiyet</th><th>Yaş</th><th>Eğitim</th><th>Meslek</th><th>Transkript</th><th>Kodlama</th><th /></tr></thead><tbody>{project.interviews.map((item, index) => <tr key={item.id}><td><button className="person-cell link-cell" onClick={() => { selectInterview(item.id); go('transcript'); }}><Avatar name={item.participant} index={index} /><span><strong>{item.participant}</strong><small>{item.name}</small></span></button></td><td>{item.participantDetails?.gender || '—'}</td><td>{item.participantDetails?.age || '—'}</td><td>{item.participantDetails?.education || '—'}</td><td>{item.participantDetails?.occupation || '—'}</td><td>{item.segments.length} satır</td><td><span className="count-pill">{item.codingUnits.length}</span></td><td><button className="ghost-icon" aria-label={`${item.participant} bilgilerini düzenle`} onClick={() => setEditing(item)}><Icon name="pencil" size={15} /></button></td></tr>)}</tbody></table></div> : <Empty icon="personPlus" title="Henüz katılımcı yok" description="İlk katılımcıyı ve transkriptini ekleyin." />}{editing && <EditParticipant interview={editing} onClose={() => setEditing(null)} onSave={(next) => { commit({ ...project, interviews: project.interviews.map((item) => item.id === next.id ? next : item) }, 'Katılımcı bilgileri güncellendi'); setEditing(null); }} />}</div>;
}

function ParticipantForm({ project, commit, onSaved, onCancel }: { project: AnalysisProject; commit: (p: AnalysisProject, s?: string) => Promise<void>; onSaved: (id: string) => void; onCancel: () => void }) {
  const [source, setSource] = useState<'transcript' | 'audio'>('transcript');
  const [name, setName] = useState('');
  const [file, setFile] = useState<File | null>(null);
  const [audioFile, setAudioFile] = useState<File | null>(null);
  const [busy, setBusy] = useState(false);
  const [transcribing, setTranscribing] = useState(false);
  const [formError, setFormError] = useState('');
  const [apiStatus, setAPIStatus] = useState<OpenAIStatus | null>(null);
  const [transcription, setTranscription] = useState<TranscriptionResult | null>(null);
  const [speakerNames, setSpeakerNames] = useState<Record<string, string>>({});

  useEffect(() => { openAIStatus().then(setAPIStatus).catch(() => setAPIStatus({ configured: false, source: null })); }, []);
  const mappedSpeakersReady = transcription ? speakersOf(transcription).every((speaker) => speakerNames[speaker]?.trim()) : false;
  const canSave = !busy && !transcribing && (source === 'transcript' ? Boolean(file) : Boolean(transcription && mappedSpeakersReady));

  async function runTranscription() {
    if (!audioFile) return;
    setTranscribing(true); setFormError(''); setTranscription(null); setSpeakerNames({});
    try {
      const status = await openAIStatus(); setAPIStatus(status);
      if (!status.configured) throw new Error('OpenAI API anahtarı bulunamadı. Native uygulamadaki Ayarlar bölümünden kaydedin ve web sunucusunu yeniden başlatın.');
      const result = await transcribeAudio(audioFile);
      setTranscription(result); setSpeakerNames(suggestedSpeakerNames(result, name || 'Katılımcı'));
    } catch (reason) { setFormError(message(reason)); }
    finally { setTranscribing(false); }
  }

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    setBusy(true); setFormError('');
    try {
      let details: ParticipantDetails = { ...emptyDetails(), gender: String(data.get('gender') ?? ''), age: String(data.get('age') ?? ''), education: String(data.get('education') ?? ''), occupation: String(data.get('occupation') ?? ''), location: String(data.get('location') ?? ''), notes: String(data.get('notes') ?? '') };
      let segments: TranscriptSegment[];
      let status: string;
      if (source === 'audio') {
        if (!audioFile || !transcription || !mappedSpeakersReady) throw new Error('Önce ses kaydını metne dönüştürün ve bütün konuşmacıları eşleştirin.');
        segments = diarizedTranscriptSegments(transcription, speakerNames);
        details = detailsWithTranscriptionProvenance(details, audioFile.name, transcription.model);
        status = `${name.trim()} için ${segments.length} zamanlı ve konuşmacılı satır eklendi`;
      } else {
        if (!file) throw new Error('Bir transkript dosyası seçin.');
        segments = await parseTranscript(file);
        status = `${name.trim()} eklendi · ${segments.length} satır içe aktarıldı`;
      }
      const interview = createInterview(name, String(data.get('interviewName')), segments, details);
      await commit({ ...project, interviews: [...project.interviews, interview] }, status);
      onSaved(interview.id);
    } catch (reason) { setFormError(message(reason)); }
    finally { setBusy(false); }
  }

  return <div className="form-page fade-in"><PageHeader title="Katılımcı Ekle" subtitle="Kişi bilgilerini girin; hazır transkript veya ses kaydıyla devam edin." /><form onSubmit={submit}><section className="form-section"><div><h3>Katılımcı bilgileri</h3><p>Analiz ve karşılaştırma ekranlarında kullanılacak bilgiler.</p></div><div className="form-grid"><label className="full">Ad Soyad<input name="name" required value={name} onChange={(event) => setName(event.target.value)} /></label><label className="full">Görüşme adı<input name="interviewName" placeholder="Boş bırakılırsa otomatik oluşturulur" /></label><label>Cinsiyet<input name="gender" /></label><label>Yaş<input name="age" /></label><label>Eğitim<input name="education" /></label><label>Meslek<input name="occupation" /></label><label>Şehir/Bölge<input name="location" /></label><label className="full">Notlar<textarea name="notes" /></label></div></section><section className="form-section"><div><h3>Görüşme kaynağı</h3><p>Hazır bir transkript yükleyin veya ses kaydını konuşmacı ve zaman bilgileriyle metne dönüştürün.</p></div><div className="source-area"><div className="source-switch" role="tablist" aria-label="Görüşme kaynağı"><button type="button" role="tab" aria-selected={source === 'transcript'} className={source === 'transcript' ? 'active' : ''} onClick={() => setSource('transcript')}><Icon name="table" size={15} /> Hazır Transkript</button><button type="button" role="tab" aria-selected={source === 'audio'} className={source === 'audio' ? 'active' : ''} onClick={() => setSource('audio')}><Icon name="waveform" size={15} /> Ses Kaydı</button></div>{source === 'transcript' ? <label className={`dropzone ${file ? 'has-file' : ''}`}><input type="file" required accept=".xlsx,.csv,.tsv,.txt,.md" hidden onChange={(event) => setFile(event.target.files?.[0] ?? null)} /><Icon name="upload" size={24} /><strong>{file?.name ?? 'Transkript dosyasını seçin'}</strong><span>XLSX, CSV, TSV, TXT veya Markdown</span></label> : <div className="audio-flow"><label className={`dropzone compact ${audioFile ? 'has-file' : ''}`}><input type="file" required accept={AUDIO_EXTENSIONS.map((extension) => `.${extension}`).join(',')} hidden onChange={(event) => { setAudioFile(event.target.files?.[0] ?? null); setTranscription(null); setSpeakerNames({}); setFormError(''); }} /><Icon name="waveform" size={24} /><strong>{audioFile?.name ?? 'Ses kaydını seçin'}</strong><span>{audioFile ? formatBytes(audioFile.size) : `MP3, MP4, MPEG, MPGA, M4A, WAV, WEBM, FLAC veya OGG · en fazla ${Math.round(MAX_AUDIO_SIZE / 1024 / 1024)} MB`}</span></label><div className={`api-status ${apiStatus?.configured ? 'ready' : ''}`}><Icon name={apiStatus?.configured ? 'shieldCheck' : 'key'} size={17} /><span><strong>{apiStatus?.configured ? 'OpenAI API anahtarı hazır' : 'OpenAI API anahtarı gerekli'}</strong><small>{apiStatus?.source === 'native-settings' ? 'Native uygulama ayarından güvenli yerel geçit üzerinden kullanılıyor.' : apiStatus?.source === 'environment' ? 'Sunucu ortam değişkeninden kullanılıyor.' : 'Native uygulamadaki Ayarlar bölümünden anahtarı kaydedin.'}</small></span></div>{transcribing ? <div className="transcribing"><span className="spinner" /><div><strong>Konuşmacılar ve zaman aralıkları çıkarılıyor…</strong><small>Dosya boyutuna göre bu işlem birkaç dakika sürebilir.</small></div></div> : !transcription && <button type="button" className="button primary full" disabled={!audioFile || !apiStatus?.configured} onClick={runTranscription}><Icon name="waveform" size={17} /> Sesi Metne Dönüştür</button>}{transcription && <><div className="speaker-mapping"><h4>Konuşmacıları eşleştir</h4><p>Ad değişikliği ilgili bütün transkript satırlarına uygulanır.</p>{speakersOf(transcription).map((speaker, index) => <label key={speaker}><i style={{ '--theme': colors[index % colors.length] } as React.CSSProperties} /><code>{speaker}</code><Icon name="chevron" size={13} /><input aria-label={`${speaker} konuşmacısının adı`} value={speakerNames[speaker] ?? ''} onChange={(event) => setSpeakerNames({ ...speakerNames, [speaker]: event.target.value })} placeholder="Konuşmacı adı" /></label>)}</div><div className="transcription-preview"><div className="preview-head"><span>Konuşmacı</span><span>Zaman</span><span>Metin</span></div>{transcription.segments.map((segment, index) => <div className="preview-row" key={`${segment.speaker}-${segment.start}-${index}`}><strong>{speakerNames[segment.speaker]?.trim() || segment.speaker}</strong><code>{displayAudioTime(segment.start)}–{displayAudioTime(segment.end, 'up')}</code><p>{segment.text}</p></div>)}</div><button type="button" className="button small" disabled={transcribing} onClick={runTranscription}>Transkripsiyonu Yeniden Oluştur</button></>}</div>}</div></section>{formError && <p className="form-error" role="alert">{formError}</p>}<div className="form-actions"><button type="button" className="button" onClick={onCancel}>Vazgeç</button><button className="button primary" disabled={!canSave}>{busy ? 'Kaydediliyor…' : 'Kaydet ve Kodlamaya Geç'}</button></div></form></div>;
}

function Transcript({ project, interview, commit }: { project: AnalysisProject; interview: Interview | null; commit: (p: AnalysisProject, s?: string) => Promise<void> }) {
  const [query, setQuery] = useState(''); const [editing, setEditing] = useState(false); const [selected, setSelected] = useState<Set<string>>(new Set());
  if (!interview) return <EmptyPage title="Transkript" />;
  const currentInterview = interview;
  const visible = currentInterview.segments.filter((segment) => `${segment.speaker} ${segment.text} ${segment.start} ${segment.end}`.toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr')));
  const replaceInterview = (next: Interview, status?: string) => commit({ ...project, interviews: project.interviews.map((item) => item.id === next.id ? next : item) }, status);
  function updateSegment(id: string, field: keyof TranscriptSegment, value: string) { replaceInterview({ ...currentInterview, segments: currentInterview.segments.map((segment) => segment.id === id ? { ...segment, [field]: value } : segment) }, 'Transkript güncellendi'); }
  function addRow() { const order = currentInterview.segments.length + 1; const next: TranscriptSegment = { id: crypto.randomUUID(), order, part: null, speaker: '', start: '', end: '', text: '' }; replaceInterview({ ...currentInterview, segments: [...currentInterview.segments, next] }, 'Yeni satır eklendi'); setSelected(new Set([next.id])); }
  function mergeRows() { const rows = currentInterview.segments.filter((segment) => selected.has(segment.id)).sort((a, b) => a.order - b.order); if (rows.length < 2) return; const first = { ...rows[0], text: rows.map((row) => row.text).join(' '), end: rows.at(-1)?.end ?? rows[0].end, speaker: [...new Set(rows.map((row) => row.speaker).filter(Boolean))].join(' / ') }; const removed = new Set(rows.slice(1).map((row) => row.id)); const segments = currentInterview.segments.filter((row) => !removed.has(row.id)).map((row) => row.id === first.id ? first : row).sort((a, b) => a.order - b.order).map((row, index) => ({ ...row, order: index + 1 })); const units = currentInterview.codingUnits.map((unit) => ({ ...unit, segmentIDs: [...new Set(unit.segmentIDs.map((id) => removed.has(id) ? first.id : id))] })); replaceInterview({ ...currentInterview, segments, codingUnits: units }, `${rows.length} satır birleştirildi`); setSelected(new Set([first.id])); }
  function deleteRows() { if (!selected.size || !window.confirm(`${selected.size} satır ve ilişkili boş kodlamalar silinsin mi?`)) return; const segments = currentInterview.segments.filter((row) => !selected.has(row.id)).map((row, index) => ({ ...row, order: index + 1 })); const units = currentInterview.codingUnits.map((unit) => ({ ...unit, segmentIDs: unit.segmentIDs.filter((id) => !selected.has(id)) })).filter((unit) => unit.segmentIDs.length); replaceInterview({ ...currentInterview, segments, codingUnits: units }, `${selected.size} satır silindi`); setSelected(new Set()); }
  return <div className="page transcript-page fade-in"><PageHeader title="Transkript" subtitle={`${currentInterview.participant} · ${currentInterview.segments.length} satır`} action={<div className="toolbar-row"><Search value={query} setValue={setQuery} placeholder="Metin veya konuşmacı ara" /><button className="button small" onClick={() => setEditing((value) => !value)}><Icon name="pencil" size={14} /> {editing ? 'Bitti' : 'Düzenle'}</button><button className="button small" onClick={addRow}><Icon name="addRow" size={14} /> Satır</button><button className="button small" disabled={selected.size < 2} onClick={mergeRows}><Icon name="merge" size={14} /> Birleştir</button><button className="button small danger" disabled={!selected.size} onClick={deleteRows}><Icon name="trash" size={14} /> Sil</button><button className="button small" onClick={() => exportTranscriptXLSX(currentInterview)}><Icon name="download" size={14} /> XLSX</button></div>} /><TranscriptTable segments={visible} selected={selected} setSelected={setSelected} editing={editing} updateSegment={updateSegment} /></div>;
}

function Coding({ project, interview, commit }: { project: AnalysisProject; interview: Interview | null; commit: (p: AnalysisProject, s?: string) => Promise<void> }) {
  const [selected, setSelected] = useState<Set<string>>(new Set()); const [themeIDs, setThemeIDs] = useState<Set<string>>(new Set()); const [memo, setMemo] = useState(''); const [themeQuery, setThemeQuery] = useState(''); const [newTheme, setNewTheme] = useState(''); const [newThemeParent, setNewThemeParent] = useState('');
  if (!interview) return <EmptyPage title="Kodlama" />;
  const currentInterview = interview; const chosen = [...selected]; const text = selectedText(currentInterview, chosen);
  const filteredThemes = project.themes.filter((theme) => themePathName(project, theme.id).toLocaleLowerCase('tr').includes(themeQuery.toLocaleLowerCase('tr')));
  async function save(keep = false) { if (!chosen.length || !themeIDs.size) return; const nextInterview = saveCodingUnit(currentInterview, chosen, [...themeIDs], memo); await commit({ ...project, interviews: project.interviews.map((item) => item.id === currentInterview.id ? nextInterview : item) }, 'Kodlama birimi ve analitik not kaydedildi'); if (!keep) { setSelected(new Set()); setThemeIDs(new Set()); setMemo(''); } }
  async function addTheme() { const name = newTheme.trim(); if (!name) return; const parent = project.themes.find((theme) => theme.id === newThemeParent); const node: ThemeNode = { id: crypto.randomUUID(), name, parentID: parent?.id ?? null, colorIndex: parent?.colorIndex ?? childrenOf(project, null).length % colors.length, note: null }; await commit({ ...project, themes: [...project.themes, node] }, `“${name}” teması eklendi`); setThemeIDs((current) => new Set(current).add(node.id)); setNewTheme(''); }
  return <div className="coding-layout fade-in"><div className="coding-transcript"><div className="inline-title"><div><h2>Kodlama</h2><p>Satırları seçerek gerçek bir kodlama birimi oluşturun.</p></div><span>{selected.size} satır seçili</span></div><TranscriptTable segments={currentInterview.segments} selected={selected} setSelected={setSelected} /></div><aside className="coding-panel"><h3>Kodlama Alanı</h3>{selected.size ? <><div className="selected-quote"><label>SEÇİLEN İFADE</label><p>“{text}”</p></div><label className="field-label">Tema seç · birden çok seçim yapılabilir</label><Search value={themeQuery} setValue={setThemeQuery} placeholder="Tema yolunda ara" /><div className="theme-options">{filteredThemes.map((theme) => <button className={`theme-option ${themeIDs.has(theme.id) ? 'selected' : ''}`} key={theme.id} onClick={() => setThemeIDs((current) => { const next = new Set(current); next.has(theme.id) ? next.delete(theme.id) : next.add(theme.id); return next; })}><span style={{ '--theme': colors[theme.colorIndex % colors.length] } as React.CSSProperties} /><span><strong>{theme.name}</strong><small>{themePathName(project, theme.id)}</small></span>{themeIDs.has(theme.id) && <Icon name="check" size={15} />}</button>)}</div><div className="theme-create"><select aria-label="Yeni temanın üst teması" value={newThemeParent} onChange={(event) => setNewThemeParent(event.target.value)}><option value="">Ana tema olarak ekle</option>{project.themes.map((theme) => <option value={theme.id} key={theme.id}>{themePathName(project, theme.id)}</option>)}</select><div className="inline-add"><input value={newTheme} onChange={(event) => setNewTheme(event.target.value)} placeholder="Yeni tema adı" /><button className="button small" onClick={addTheme}><Icon name="plus" size={14} /></button></div></div><label className="field-label">Analitik not</label><textarea value={memo} onChange={(event) => setMemo(event.target.value)} placeholder="Bu ifade hakkında analitik not…" /><div className="coding-actions"><button className="button" disabled={!themeIDs.size} onClick={() => save(true)}>Kaydet ve devam et</button><button className="button primary" disabled={!themeIDs.size} onClick={() => save(false)}><Icon name="tag" size={16} /> Kaydet ve bitir</button></div></> : <Empty icon="tag" title="Önce satır seçin" description="Bir veya daha fazla transkript satırını seçerek kodlamaya başlayın." />}</aside></div>;
}

function TranscriptTable({ segments, selected, setSelected, editing = false, updateSegment }: { segments: TranscriptSegment[]; selected: Set<string>; setSelected: (next: Set<string>) => void; editing?: boolean; updateSegment?: (id: string, field: keyof TranscriptSegment, value: string) => void }) {
  function toggle(id: string) { const next = new Set(selected); next.has(id) ? next.delete(id) : next.add(id); setSelected(next); }
  return <div className="table-wrap transcript-table"><table><thead><tr><th><span className="sr-only">Seç</span></th><th>#</th><th>Başlangıç</th><th>Bitiş</th><th>Konuşmacı</th><th>Metin</th></tr></thead><tbody>{segments.map((segment) => <tr key={segment.id} className={selected.has(segment.id) ? 'selected' : ''}><td><button className="row-check" aria-pressed={selected.has(segment.id)} aria-label={`${segment.order}. satırı seç`} onClick={() => toggle(segment.id)}>{selected.has(segment.id) && <Icon name="check" size={13} />}</button></td><td>{segment.order}</td><td>{editing ? <input value={segment.start} onChange={(event) => updateSegment?.(segment.id, 'start', event.target.value)} /> : <span className="mono">{segment.start}</span>}</td><td>{editing ? <input value={segment.end} onChange={(event) => updateSegment?.(segment.id, 'end', event.target.value)} /> : <span className="mono">{segment.end}</span>}</td><td>{editing ? <input value={segment.speaker} onChange={(event) => updateSegment?.(segment.id, 'speaker', event.target.value)} /> : <span className="speaker">{segment.speaker || '—'}</span>}</td><td>{editing ? <textarea value={segment.text} onChange={(event) => updateSegment?.(segment.id, 'text', event.target.value)} /> : segment.text}</td></tr>)}</tbody></table></div>;
}

interface Quote { interview: Interview; unit: CodingUnit; text: string; paths: string[]; segments: TranscriptSegment[] }
function projectQuotes(project: AnalysisProject): Quote[] { return project.interviews.flatMap((interview) => interview.codingUnits.map((unit) => ({ interview, unit, text: selectedText(interview, unit.segmentIDs), paths: unit.themeIDs.map((id) => themePathName(project, id)), segments: interview.segments.filter((segment) => unit.segmentIDs.includes(segment.id)).sort((a, b) => a.order - b.order) }))); }

function CodedQuotes({ project, commit }: { project: AnalysisProject; commit: (p: AnalysisProject, s?: string) => Promise<void> }) {
  const [query, setQuery] = useState(''); const [themeFilter, setThemeFilter] = useState<string | null>(null); const quotes = projectQuotes(project).filter((quote) => { const matchesText = `${quote.text} ${quote.unit.memo} ${quote.interview.participant} ${quote.paths.join(' ')}`.toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr')); const matchesTheme = !themeFilter || quote.unit.themeIDs.some((id) => themePath(project, id).some((theme) => theme.id === themeFilter)); return matchesText && matchesTheme; });
  function remove(quote: Quote) { if (!window.confirm('Bu kodlama birimi kaldırılsın mı?')) return; const next = removeCodingUnit(quote.interview, quote.unit.id); commit({ ...project, interviews: project.interviews.map((item) => item.id === next.id ? next : item) }, 'Kodlama kaldırıldı'); }
  return <div className="page fade-in"><PageHeader title="Kodlanmış Alıntılar" subtitle={`${quotes.length} kodlama birimi · tamamı proje verisinden`} action={<div className="toolbar-row"><Search value={query} setValue={setQuery} placeholder="Alıntı, tema veya not ara" /><button className="button small" onClick={() => exportQuotesXLSX(project)}><Icon name="download" size={14} /> XLSX</button></div>} /><div className="filterbar"><button className={`chip ${!themeFilter ? 'active' : ''}`} onClick={() => setThemeFilter(null)}>Tümü</button>{childrenOf(project, null).map((theme) => <button className={`chip ${themeFilter === theme.id ? 'active' : ''}`} key={theme.id} onClick={() => setThemeFilter(theme.id)}>{theme.name}</button>)}</div>{quotes.length ? <div className="quote-list">{quotes.map((quote, index) => <article className="quote-card" key={quote.unit.id}><div className="quote-meta"><Avatar name={quote.interview.participant} index={index} mini /><strong>{quote.interview.participant}</strong><span>{quote.segments[0]?.start || '—'}–{quote.segments.at(-1)?.end || '—'}</span><button className="ghost-icon" aria-label="Kodlamayı kaldır" onClick={() => remove(quote)}><Icon name="trash" size={14} /></button></div><blockquote>{quote.text}</blockquote>{quote.unit.memo && <p className="memo">{quote.unit.memo}</p>}<div className="tag-list">{quote.paths.map((path, pathIndex) => <span key={path} style={{ '--theme': colors[pathIndex % colors.length] } as React.CSSProperties}>{path}</span>)}</div></article>)}</div> : <Empty icon="filter" title="Eşleşen alıntı yok" description="Kodlama ekranından bir ifade kodlayın veya filtreleri temizleyin." />}</div>;
}

function Overview({ project, selectInterview, go }: { project: AnalysisProject; selectInterview: (id: string) => void; go: (s: Section) => void }) {
  const rows = project.interviews.reduce((sum, item) => sum + item.segments.length, 0), units = project.interviews.reduce((sum, item) => sum + item.codingUnits.length, 0), usage = themeUsage(project).filter((item) => item.codingCount);
  return <div className="page fade-in"><PageHeader title={project.name} subtitle="Vakalar arası çalışma alanı" /><div className="metric-grid">{[['people', 'Görüşme', project.interviews.length], ['table', 'Transkript satırı', rows], ['tag', 'Kodlama birimi', units], ['map', 'Kullanılan tema', usage.length]].map(([icon, title, value]) => <article className="metric-card" key={String(title)}><Icon name={String(icon)} size={20} /><strong>{value}</strong><span>{title}</span></article>)}</div><div className="overview-grid"><section className="panel"><h3>Görüşmeler</h3>{project.interviews.map((item, index) => <button className="interview-row" key={item.id} onClick={() => { selectInterview(item.id); go('transcript'); }}><Avatar name={item.participant} index={index} mini /><span><strong>{item.name}</strong><small>{item.participant}</small></span><span>{item.segments.length} satır</span><b>{item.codingUnits.length} kodlama</b><Icon name="chevron" size={14} /></button>)}</section><section className="panel"><h3>En sık kullanılan temalar</h3>{usage.length ? usage.slice(0, 8).map((item, index) => <div className="usage-row" key={item.theme.id}><span>{item.theme.name}</span><div><i style={{ width: `${Math.max(5, item.codingCount / usage[0].codingCount * 100)}%`, '--theme': colors[item.theme.colorIndex % colors.length] } as React.CSSProperties} /></div><b>{item.codingCount}</b></div>) : <p className="muted">Henüz tema kullanımı yok.</p>}</section></div><p className="footnote">Sayılar temaların önemini değil, yalnızca kodlama kayıtlarının dağılımını gösterir.</p></div>;
}

function Analytics({ project, type }: { project: AnalysisProject; type: Section }) {
  const usage = themeUsage(project), max = Math.max(1, ...usage.map((item) => type === 'prevalence' ? item.participantCount : item.codingCount));
  const titles: Partial<Record<Section, string>> = { profile: 'Baskınlık Profili', frequency: 'İçerik Analizi', miles: 'Miles–Huberman Matrisi', prevalence: 'Katılımcı Yaygınlığı', framework: 'Framework Matrix' };
  if (type === 'framework') return <Framework project={project} />;
  return <div className="page fade-in"><PageHeader title={titles[type] ?? 'Analiz'} subtitle="Sonuçlar mevcut kodlama birimlerinden gerçek zamanlı hesaplanır." /><div className="analytics-grid"><section className="panel chart-panel"><h3>Tema dağılımı</h3><div className="bar-chart">{usage.filter((item) => item.codingCount).map((item) => { const value = type === 'prevalence' ? item.participantCount : item.codingCount; return <div className="bar-row" key={item.theme.id}><span>{item.theme.name}</span><div><i style={{ width: `${value / max * 100}%`, '--theme': colors[item.theme.colorIndex % colors.length] } as React.CSSProperties}><b>{value}</b></i></div></div>; })}</div></section><section className="panel insight-panel"><h3>Analitik sınırlar</h3><div className="insight-hero"><span><Icon name="chart" size={22} /></span><strong>{usage[0]?.theme.name ?? 'Henüz veri yok'}</strong><p>{usage[0] ? `${usage[0].codingCount} kodlama · ${usage[0].participantCount} katılımcı` : 'İlk kodlamadan sonra hesaplanır.'}</p></div><ul><li>Alt tema atamaları üst tema toplamına dahil edilir.</li><li>Yaygınlık, temanın görüldüğü benzersiz katılımcı sayısıdır.</li><li>Frekans analitik önem iddiası değildir.</li></ul></section></div></div>;
}

function Framework({ project }: { project: AnalysisProject }) {
  const themes = childrenOf(project, null); return <div className="page fade-in"><PageHeader title="Framework Matrix" subtitle="Hücreler katılımcının ilgili temaya bağlı gerçek alıntılarından oluşturulur." action={<button className="button small" onClick={() => exportQuotesXLSX(project)}><Icon name="download" size={14} /> XLSX</button>} /><div className="table-wrap framework-table"><table><thead><tr><th>Katılımcı</th>{themes.map((theme) => <th key={theme.id}>{theme.name}</th>)}</tr></thead><tbody>{project.interviews.map((interview) => <tr key={interview.id}><td><strong>{interview.participant}</strong><small>{interview.participantDetails?.occupation}</small></td>{themes.map((theme) => { const units = interview.codingUnits.filter((unit) => unit.themeIDs.some((id) => themePath(project, id).some((node) => node.id === theme.id))); return <td key={theme.id}>{units.length ? units.map((unit) => selectedText(interview, unit.segmentIDs)).join(' · ') : <span className="muted">—</span>}</td>; })}</tr>)}</tbody></table></div></div>;
}

function ThemeMap({ project, commit }: { project: AnalysisProject; commit: (p: AnalysisProject, s?: string) => Promise<void> }) {
  const [zoom, setZoom] = useState(1); const [pan, setPan] = useState({ x: 0, y: 0 }); const [collapsed, setCollapsed] = useState<Set<string>>(new Set()); const [selected, setSelected] = useState<string | null>(null); const [query, setQuery] = useState(''); const [note, setNote] = useState(''); const [replacement, setReplacement] = useState<Record<string, string>>({}); const drag = useRef<{ x: number; y: number; panX: number; panY: number } | null>(null); const viewport = useRef<HTMLDivElement | null>(null);
  const effectiveCollapsed = query.trim() ? new Set<string>() : collapsed;
  const layout = useMemo(() => createThemeMapLayout(project, effectiveCollapsed), [project, collapsed, query]);
  const selectedTheme = project.themes.find((theme) => theme.id === selected) ?? null;
  const evidence = useMemo(() => selected ? themeEvidence(project, selected) : [], [project, selected]);
  const evidenceCounts = useMemo(() => new Map(themeUsage(project).map((item) => [item.theme.id, item.codingCount])), [project]);
  useEffect(() => { setNote(selectedTheme?.note ?? ''); }, [selectedTheme?.id, selectedTheme?.note]);
  useEffect(() => { const handler = () => fit(); window.addEventListener('resize', handler); const frame = requestAnimationFrame(handler); return () => { window.removeEventListener('resize', handler); cancelAnimationFrame(frame); }; }, [layout.width, layout.height]);

  function fit() { const element = viewport.current; if (!element) return; const nextZoom = Math.max(.2, Math.min(1.15, Math.min((element.clientWidth - 70) / layout.width, (element.clientHeight - 70) / layout.height))); setZoom(nextZoom); setPan({ x: (element.clientWidth - layout.width * nextZoom) / 2, y: (element.clientHeight - layout.height * nextZoom) / 2 }); }
  function pointerDown(event: ReactPointerEvent<HTMLDivElement>) { if ((event.target as HTMLElement).closest('.map-node,.map-hint')) return; drag.current = { x: event.clientX, y: event.clientY, panX: pan.x, panY: pan.y }; event.currentTarget.setPointerCapture(event.pointerId); }
  function pointerMove(event: ReactPointerEvent<HTMLDivElement>) { if (!drag.current) return; setPan({ x: drag.current.panX + event.clientX - drag.current.x, y: drag.current.panY + event.clientY - drag.current.y }); }
  function wheel(event: WheelEvent<HTMLDivElement>) { event.preventDefault(); const element = viewport.current; if (!element) return; const rect = element.getBoundingClientRect(); const nextZoom = Math.max(.2, Math.min(2.2, zoom - event.deltaY * .001)); const contentX = (event.clientX - rect.left - pan.x) / zoom; const contentY = (event.clientY - rect.top - pan.y) / zoom; setPan({ x: event.clientX - rect.left - contentX * nextZoom, y: event.clientY - rect.top - contentY * nextZoom }); setZoom(nextZoom); }
  function toggleBranch(id: string) { setCollapsed((current) => { const next = new Set(current); next.has(id) ? next.delete(id) : next.add(id); return next; }); }
  async function saveNote() { if (!selectedTheme || note === (selectedTheme.note ?? '')) return; await commit({ ...project, themes: project.themes.map((theme) => theme.id === selectedTheme.id ? { ...theme, note: note.trim() || null } : theme) }, 'Tema anlatısı kaydedildi'); }
  async function removeAssignment(item: ThemeEvidenceItem) { if (!selected) return; const interviews = project.interviews.map((interview) => interview.id !== item.interviewID ? interview : { ...interview, codingUnits: interview.codingUnits.flatMap((unit) => { if (unit.id !== item.unitID) return [unit]; const themeIDs = unit.themeIDs.filter((id) => !isThemeDescendant(project, id, selected)); return themeIDs.length ? [{ ...unit, themeIDs }] : []; }) }); await commit({ ...project, interviews }, 'Tema ataması kaldırıldı'); }
  async function replaceAssignment(item: ThemeEvidenceItem) { if (!selected) return; const replacementID = replacement[item.unitID]; if (!replacementID) return; const interviews = project.interviews.map((interview) => interview.id !== item.interviewID ? interview : { ...interview, codingUnits: interview.codingUnits.map((unit) => unit.id !== item.unitID ? unit : { ...unit, themeIDs: [...new Set([...unit.themeIDs.filter((id) => !isThemeDescendant(project, id, selected)), replacementID])] }) }); await commit({ ...project, interviews }, 'Tema ataması güncellendi'); setReplacement((current) => ({ ...current, [item.unitID]: '' })); }
  function connector(from: { x: number; y: number }, to: { x: number; y: number }, center = false) { const goesRight = to.x > from.x; const fromWidth = center ? 140 : 190; const startX = goesRight ? from.x + fromWidth : from.x; const endX = goesRight ? to.x : to.x + 190; const startY = from.y + 24; const endY = to.y + 24; const middle = (startX + endX) / 2; return `M${startX},${startY} C${middle},${startY} ${middle},${endY} ${endX},${endY}`; }

  return <div className="map-page fade-in"><div className="map-toolbar"><div><h2>Tema Haritası</h2><p>{project.themes.length} düğüm · sınırsız hiyerarşi</p></div><Search value={query} setValue={setQuery} placeholder="Haritada tema ara" /><button className="ghost-icon" aria-label="Uzaklaştır" onClick={() => setZoom((value) => Math.max(.2, value - .1))}><Icon name="zoomOut" size={17} /></button><input aria-label="Harita yakınlaştırma" type="range" min="20" max="220" value={zoom * 100} onChange={(event) => setZoom(Number(event.target.value) / 100)} /><span className="zoom-value">{Math.round(zoom * 100)}%</span><button className="ghost-icon" aria-label="Yakınlaştır" onClick={() => setZoom((value) => Math.min(2.2, value + .1))}><Icon name="zoomIn" size={17} /></button><div className="branch-actions"><button className="button small" onClick={() => setCollapsed(new Set())}>Tümünü Aç</button><button className="button small" onClick={() => setCollapsed(new Set(project.themes.filter((theme) => childrenOf(project, theme.id).length).map((theme) => theme.id)))}>Daralt</button></div><button className="button small" onClick={fit}><Icon name="maximize" size={15} /> Sığdır</button></div><div className="map-workspace"><div ref={viewport} className="map-viewport" onPointerDown={pointerDown} onPointerMove={pointerMove} onPointerUp={() => { drag.current = null; }} onPointerCancel={() => { drag.current = null; }} onWheel={wheel} onClick={(event) => { if (event.target === event.currentTarget) setSelected(null); }}><div className="dynamic-map-canvas" style={{ width: layout.width, height: layout.height, transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom})` }}><svg aria-hidden="true" viewBox={`0 0 ${layout.width} ${layout.height}`}>{layout.rootIDs.map((id) => { const to = layout.positions.get(id), theme = project.themes.find((item) => item.id === id); return to ? <path key={`root-${id}`} d={connector(layout.center, to, true)} stroke={colors[(theme?.colorIndex ?? 0) % colors.length]} /> : null; })}{layout.edges.map((edge) => { const from = layout.positions.get(edge.parent), to = layout.positions.get(edge.child); return from && to ? <path key={`${edge.parent}-${edge.child}`} d={connector(from, to)} stroke={colors[edge.color % colors.length]} /> : null; })}</svg><div className="map-center" style={{ left: layout.center.x, top: layout.center.y }}>Temalar</div>{layout.visible.map((theme) => { const children = childrenOf(project, theme.id); const position = layout.positions.get(theme.id)!; const highlighted = Boolean(query.trim() && themePathName(project, theme.id).toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr'))); return <div key={theme.id} className={`map-node ${selected === theme.id ? 'expanded' : ''} ${highlighted ? 'highlight' : ''} ${theme.parentID == null ? 'root-theme' : ''}`} style={{ '--theme': colors[theme.colorIndex % colors.length], left: position.x, top: position.y } as React.CSSProperties}><button className="map-node-main" onClick={() => setSelected(theme.id)}><i /><span>{theme.name}<small>{evidenceCounts.get(theme.id) ?? 0} alıntı</small></span></button>{children.length > 0 && <button className="map-collapse" aria-label={collapsed.has(theme.id) ? `${children.length} alt temayı aç` : 'Alt temaları daralt'} aria-expanded={!collapsed.has(theme.id)} onClick={() => toggleBranch(theme.id)}><Icon name="chevron" size={13} /></button>}</div>; })}</div><div className="map-hint">Boş alanda sürükleyin · tekerlek ile yakınlaştırın · düğmeye basarak dalları yönetin</div></div>{selectedTheme && <aside className="map-inspector"><div className="inspector-head"><div><small>TEMA</small><h3>{selectedTheme.name}</h3><p>{themePathName(project, selectedTheme.id)}</p></div><button className="ghost-icon" aria-label="Tema denetçisini kapat" onClick={() => setSelected(null)}><Icon name="close" /></button></div><label className="theme-note-label"><span>Tema anlatısı <small>Odaktan çıkınca kaydedilir</small></span><textarea value={note} onChange={(event) => setNote(event.target.value)} onBlur={saveNote} placeholder="Bu temanın kapsamını, sınırlarını ve analitik anlamını açıklayın…" /></label><h4>Bağlı alıntılar · {evidence.length}</h4>{evidence.length ? evidence.map((item, index) => <article key={`${item.interviewID}-${item.unitID}`} style={{ '--participant': colors[index % colors.length] } as React.CSSProperties}><div className="evidence-meta"><Avatar name={item.participant} index={index} mini /><span><strong>{item.participant}</strong><small>{item.interview} · {item.time}</small></span></div><p>“{item.text}”</p>{item.assignedPaths.map((path) => <span className="evidence-path" key={path}>{path}</span>)}{item.memo && <small className="evidence-memo">{item.memo}</small>}<div className="evidence-actions"><select aria-label="Yeni tema" value={replacement[item.unitID] ?? ''} onChange={(event) => setReplacement({ ...replacement, [item.unitID]: event.target.value })}><option value="">Temayı değiştir…</option>{project.themes.filter((theme) => !isThemeDescendant(project, theme.id, selectedTheme.id)).map((theme) => <option value={theme.id} key={theme.id}>{themePathName(project, theme.id)}</option>)}</select><button className="button small" disabled={!replacement[item.unitID]} onClick={() => replaceAssignment(item)}>Uygula</button><button className="ghost-icon danger" aria-label="Tema atamasını kaldır" onClick={() => removeAssignment(item)}><Icon name="trash" size={14} /></button></div></article>) : <div className="inspector-empty"><Icon name="filter" size={23} /><strong>Bağlı alıntı yok</strong><p>Bu tema veya alt temaları henüz bir ifadeye atanmamış.</p></div>}</aside>}</div></div>;
}

function EditParticipant({ interview, onClose, onSave }: { interview: Interview; onClose: () => void; onSave: (interview: Interview) => void }) {
  const [name, setName] = useState(interview.participant); const [interviewName, setInterviewName] = useState(interview.name); const [details, setDetails] = useState({ ...emptyDetails(), ...interview.participantDetails });
  return <Modal title="Katılımcıyı Düzenle" onClose={onClose}><div className="form-grid"><label className="full">Ad Soyad<input value={name} onChange={(event) => setName(event.target.value)} /></label><label className="full">Görüşme adı<input value={interviewName} onChange={(event) => setInterviewName(event.target.value)} /></label><label>Yaş<input value={details.age} onChange={(event) => setDetails({ ...details, age: event.target.value })} /></label><label>Meslek<input value={details.occupation} onChange={(event) => setDetails({ ...details, occupation: event.target.value })} /></label><label>Eğitim<input value={details.education} onChange={(event) => setDetails({ ...details, education: event.target.value })} /></label><label>Şehir/Bölge<input value={details.location} onChange={(event) => setDetails({ ...details, location: event.target.value })} /></label></div><div className="modal-actions"><button className="button" onClick={onClose}>Vazgeç</button><button className="button primary" disabled={!name.trim()} onClick={() => onSave({ ...interview, participant: name.trim(), name: interviewName.trim() || `${name.trim()} Transkripti`, participantDetails: details })}>Kaydet</button></div></Modal>;
}

function NewProjectModal({ onClose, onCreate }: { onClose: () => void; onCreate: (name: string) => void }) { const [name, setName] = useState(''); return <Modal title="Yeni Tematik Analiz Projesi" onClose={onClose}><p>Katılımcılar, transkriptler, temalar ve kodlamalar bu projede birlikte saklanır.</p><label className="modal-label">Proje adı<input autoFocus value={name} onChange={(event) => setName(event.target.value)} onKeyDown={(event) => { if (event.key === 'Enter') onCreate(name); }} /></label><div className="modal-actions"><button className="button" onClick={onClose}>Vazgeç</button><button className="button primary" disabled={!name.trim()} onClick={() => onCreate(name)}>Proje Oluştur</button></div></Modal>; }
function SettingsModal({ theme, locale, setTheme, setLocale, onClose }: { theme: string; locale: Locale; setTheme: (v: string) => void; setLocale: (v: Locale) => void; onClose: () => void }) { const [apiStatus, setAPIStatus] = useState<OpenAIStatus | null>(null); const [apiKey, setAPIKey] = useState(''); const [checking, setChecking] = useState(false); const [apiMessage, setAPIMessage] = useState(''); const refresh = () => { setChecking(true); openAIStatus().then(setAPIStatus).catch(() => setAPIStatus({ configured: false, source: null })).finally(() => setChecking(false)); }; const saveKey = async () => { setChecking(true); setAPIMessage(''); try { setAPIStatus(await saveOpenAIKey(apiKey)); setAPIKey(''); setAPIMessage('API anahtarı Keychain’e güvenli biçimde kaydedildi.'); } catch (reason) { setAPIMessage(message(reason)); } finally { setChecking(false); } }; const removeKey = async () => { if (!window.confirm('Kayıtlı OpenAI API anahtarı silinsin mi?')) return; setChecking(true); setAPIMessage(''); try { setAPIStatus(await deleteOpenAIKey()); setAPIKey(''); setAPIMessage('API anahtarı silindi.'); } catch (reason) { setAPIMessage(message(reason)); } finally { setChecking(false); } }; useEffect(refresh, []); return <Modal title="Ayarlar" onClose={onClose}><div className="settings-list"><label>Görünüm<select value={theme} onChange={(event) => setTheme(event.target.value)}><option value="light">Açık</option><option value="dark">Koyu</option></select></label><label>Dil<select value={locale} onChange={(event) => setLocale(event.target.value as Locale)}><option value="tr">Türkçe</option><option value="en">English</option></select></label><div className="settings-openai"><strong>OpenAI</strong><p>Ses kayıtlarını zaman ve konuşmacı bilgileriyle metne dönüştürmek için kullanılır.</p><div className={`api-status ${apiStatus?.configured ? 'ready' : ''}`}><Icon name={apiStatus?.configured ? 'shieldCheck' : 'key'} size={17} /><span><strong>{apiStatus?.configured ? 'API anahtarı hazır' : 'API anahtarı bulunamadı'}</strong><small>{apiStatus?.source === 'native-settings' ? 'macOS Keychain’de saklanıyor; tarayıcıya geri okunmuyor.' : apiStatus?.source === 'environment' ? 'OPENAI_API_KEY ortam değişkeni kullanılıyor.' : 'Anahtarı aşağıdan güvenli yerel geçide kaydedin.'}</small></span><button className="button small" disabled={checking} onClick={refresh}>{checking ? 'Kontrol…' : 'Yenile'}</button></div><label className="api-key-field">OpenAI API anahtarı<input type="password" autoComplete="off" value={apiKey} onChange={(event) => setAPIKey(event.target.value)} placeholder="sk-…" /></label><div className="api-key-actions">{apiStatus?.configured && apiStatus.source !== 'environment' && <button className="button small danger" disabled={checking} onClick={removeKey}>Anahtarı Sil</button>}<button className="button small primary" disabled={checking || apiKey.trim().length < 20} onClick={saveKey}>Kaydet</button></div>{apiMessage && <p className="settings-message" role="status">{apiMessage}</p>}</div><div><strong>Veri saklama</strong><p>Projeler origin’e özel IndexedDB’de saklanır. Araştırma verilerini düzenli olarak JSON yedeğiyle dışa aktarın.</p></div></div><div className="modal-actions"><button className="button primary" onClick={onClose}>Tamam</button></div></Modal>; }
function AlertModal({ message: text, onClose }: { message: string; onClose: () => void }) { return <Modal title="İşlem tamamlanamadı" onClose={onClose}><p role="alert">{text}</p><div className="modal-actions"><button className="button primary" onClick={onClose}>Tamam</button></div></Modal>; }
function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: React.ReactNode }) { return <div className="modal-backdrop visible" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section className="modal" role="dialog" aria-modal="true" aria-label={title}><div className="modal-title"><h2>{title}</h2><button className="ghost-icon" aria-label="Kapat" onClick={onClose}><Icon name="close" /></button></div>{children}</section></div>; }
function PageHeader({ title, subtitle, action }: { title: string; subtitle: string; action?: React.ReactNode }) { return <div className="page-header"><div><h2>{title}</h2><p>{subtitle}</p></div>{action}</div>; }
function Search({ value, setValue, placeholder }: { value: string; setValue: (value: string) => void; placeholder: string }) { return <label className="searchbox"><Icon name="search" size={15} /><span className="sr-only">{placeholder}</span><input value={value} onChange={(event) => setValue(event.target.value)} placeholder={placeholder} /></label>; }
function Empty({ icon, title, description }: { icon: string; title: string; description: string }) { return <div className="empty-state"><Icon name={icon} size={28} /><h3>{title}</h3><p>{description}</p></div>; }
function EmptyPage({ title }: { title: string }) { return <div className="page full-empty"><Empty icon="personPlus" title={`${title} için görüşme seçilmedi`} description="Önce bir katılımcı ve transkript ekleyin." /></div>; }
function Avatar({ name, index = 0, mini = false }: { name: string; index?: number; mini?: boolean }) { return <span className={`avatar c${index % 5} ${mini ? 'mini' : ''}`}>{name.split(/\s+/).slice(0, 2).map((part) => part[0]).join('').toLocaleUpperCase('tr')}</span>; }
function message(reason: unknown) { return reason instanceof Error ? reason.message : String(reason); }
function formatDate(value: string) { const date = new Date(value); return Number.isNaN(date.getTime()) ? '—' : new Intl.DateTimeFormat('tr-TR', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }).format(date); }
function formatBytes(value: number) { return new Intl.NumberFormat('tr-TR', { style: 'unit', unit: value >= 1024 * 1024 ? 'megabyte' : 'kilobyte', maximumFractionDigits: 1 }).format(value / (value >= 1024 * 1024 ? 1024 * 1024 : 1024)); }
function sectionTitle(section: Section) { for (const [, items] of navGroups) for (const [id, title] of items) if (id === section) return title; return 'Tematik Analiz'; }
function translateNav(value: string, locale: Locale) { if (locale === 'tr') return value; const map: Record<string, string> = { 'Katılımcı Ekle': 'Add Participant', Katılımcılar: 'Participants', Transkript: 'Transcript', Kodlama: 'Coding', 'Kodlanmış Alıntılar': 'Coded Quotes', 'Tüm Görüşmeler': 'All Interviews', 'Tema Haritası': 'Theme Map', 'Baskınlık Profili': 'Dominance Profile', 'İçerik Analizi': 'Content Analysis', 'Katılımcı Yaygınlığı': 'Participant Prevalence' }; return map[value] ?? value; }
